"""Store bounded, redacted failure evidence outside application releases."""
from __future__ import annotations

import json
from functools import lru_cache
from collections.abc import Mapping
import os
from pathlib import Path
import re
import threading
import time
import traceback
from urllib.parse import urlsplit, urlunsplit
from uuid import uuid4


REPOSITORY_ROOT = Path(__file__).resolve().parents[1]


@lru_cache(maxsize=16)
def release_id(root: Path | None = None) -> str:
    """Read the immutable release identity generated by deployment."""
    path = (root or REPOSITORY_ROOT) / "RELEASE_SHA"
    return path.read_text(encoding="utf-8").strip() if path.is_file() else "development"


def redact(value):
    """Remove credentials, URL queries, and known environment secrets from evidence."""
    sensitive = re.compile(r"token|secret|password|authorization|cookie|api.?key|credential", re.I)
    if isinstance(value, Mapping):
        return {str(key): "[REDACTED]" if sensitive.search(str(key)) else redact(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [redact(item) for item in value]
    if not isinstance(value, str):
        if value is None or isinstance(value, (int, float, bool)):
            return value
        return redact(str(value))
    text = value
    for key, secret in os.environ.items():
        if sensitive.search(key) and len(secret) >= 6:
            text = text.replace(secret, "[REDACTED]")
    def clean_url(match):
        try:
            parts = urlsplit(match.group(0))
            host = parts.hostname or ""
            if parts.port:
                host += ":" + str(parts.port)
            return urlunsplit((parts.scheme, host, parts.path, "[REDACTED]" if parts.query else "", ""))
        except ValueError:
            return "[REDACTED URL]"
    text = re.sub(r"https?://[^\s<>\"']+", clean_url, text)
    text = re.sub(r"(?i)(bearer\s+)[A-Za-z0-9._~+/=-]+", r"\1[REDACTED]", text)
    text = re.sub(r"(?i)((?:api[_-]?key|access[_-]?token|refresh[_-]?token|password|client_secret)\s*[=:]\s*)[^\s,;]+", r"\1[REDACTED]", text)
    return text[:24000]


def atomic_json(path: Path, value) -> None:
    """Replace one control record without exposing a partial write."""
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name("." + path.name + "." + uuid4().hex)
    descriptor = os.open(temporary, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    with os.fdopen(descriptor, "w", encoding="utf-8") as output:
        json.dump(value, output, sort_keys=True, indent=2)
        output.flush()
        os.fsync(output.fileno())
    os.replace(temporary, path)


class IncidentStore:
    """Retain failure context with deduplication and a fixed storage bound."""

    def __init__(self, directory: Path, *, release: str | None = None, clock=time.time, limit: int = 100):
        self.directory = Path(directory)
        self.release = release or release_id()
        self.clock, self.limit = clock, limit
        self._last = {}
        self._lock = threading.Lock()

    def record(self, kind: str, *, component: str, error=None, context=None) -> str | None:
        """Record an incident without allowing evidence storage to stop recovery."""
        with self._lock:
            now = self.clock()
            message = redact(str(error)) if error is not None else ""
            identity = kind, component, message
            if now - self._last.get(identity, float("-inf")) < 60:
                return None
            identifier = str(int(now * 1000)) + "-" + uuid4().hex[:10]
            trace = "".join(traceback.format_exception(error)) if isinstance(error, BaseException) else ""
            value = {"schema_version": 1, "id": identifier, "time": now, "release": self.release,
                     "pid": os.getpid(), "kind": kind, "component": component,
                     "error_type": type(error).__name__ if isinstance(error, BaseException) else None,
                     "message": message, "traceback": redact(trace), "context": redact(context or {})}
            try:
                atomic_json(self.directory / (identifier + ".json"), value)
                self._last[identity] = now
                if len(self._last) > self.limit * 2:
                    self._last = dict(sorted(self._last.items(), key=lambda item: item[1])[-self.limit:])
                for path in sorted(self.directory.glob("*.json"))[:-self.limit]:
                    path.unlink()
            except (OSError, ValueError, TypeError):
                return None
            return identifier
